// Isolation test (OS-12) — construct CommitmentLedger with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { height } from "../src/kernel/index.js";
import type { Currency, Unit } from "../src/catalog/index.js";
import { CommitmentLedger, type InvalidationReader } from "../src/facts/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";

const u = "u1" as Unit;
const c = "c0" as Currency;
const never: InvalidationReader = { isInvalidated: () => false };
const always: InvalidationReader = { isInvalidated: () => true };

describe("CommitmentLedger in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new CommitmentLedger({ invalidations: never } as never)).toThrow();
    expect(() => new CommitmentLedger({ record: inMemoryRecord() } as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new CommitmentLedger({ record: {} as never, invalidations: never })).toThrow();
    expect(() => new CommitmentLedger({ record: inMemoryRecord(), invalidations: {} as never })).toThrow();
  });

  it("commit answers differently when record differs", () => {
    const busy = inMemoryRecord();
    busy.noise();
    const a = new CommitmentLedger({ record: inMemoryRecord(), invalidations: never }).commit(u, c, "HUMAN");
    const b = new CommitmentLedger({ record: busy, invalidations: never }).commit(u, c, "HUMAN");
    expect(a).not.toEqual(b);
  });

  it("effectiveCommitment answers differently when record differs", () => {
    const committed = inMemoryRecord();
    const at = new CommitmentLedger({ record: committed, invalidations: never }).commit(u, c, "HUMAN").at;
    const a = new CommitmentLedger({ record: committed, invalidations: never }).effectiveCommitment(u, c, at);
    const b = new CommitmentLedger({ record: inMemoryRecord(), invalidations: never }).effectiveCommitment(u, c, height(1));
    expect(a).not.toEqual(b);
  });

  it("effectiveCommitment answers differently when invalidations differs", () => {
    const record = inMemoryRecord();
    const at = new CommitmentLedger({ record, invalidations: never }).commit(u, c, "HUMAN").at;
    const a = new CommitmentLedger({ record, invalidations: never }).effectiveCommitment(u, c, at);
    const b = new CommitmentLedger({ record, invalidations: always }).effectiveCommitment(u, c, at);
    expect(a).not.toEqual(b);
  });
});
